package discovery

import (
	"log/slog"

	"github.com/altessa-s/rmcloud-go/internal/port"
)

//go:generate optgen generate --source-file $GOFILE

// options are a [Resolver]'s tunables. The With options are generated by
// go-optgen; a nil argument is ignored.
type options struct {
	// tokens supplies the user token whose tectonic claim names a region.
	// A pinned resolver drops it.
	tokens TokenSource `optgen:"notnil"`

	// pinned keeps the configured hosts: discovery is not called, and the
	// token source is not asked.
	pinned bool

	// trip is the GET that reads the host list. It must send no token and no
	// User-Agent and must not follow redirects; httpapi.Discovery is that
	// transport. Absent leaves discovery off.
	trip port.RoundTripper `opt:"Discovery" optgen:"notnil"`

	// log receives the resolver's records. The default is slog.Default as
	// it stands when the resolver is built.
	log *slog.Logger `opt:"Logger" optgen:"default=slog.Default()"`
}
